CREATE TABLE routers (router_id UUID PRIMARY KEY NOT NULL, router_parent_core_id UUID NULL, router_type VARCHAR(255), router_vendor VARCHAR(255), router_model VARCHAR(255), router_ip_protocol VARCHAR(255), router_ip_address VARCHAR(255), location_id int NULL);
CREATE TABLE location (location_id int NOT NULL PRIMARY KEY, address VARCHAR(255), city VARCHAR(255), state VARCHAR(255), zipcode VARCHAR(255), country VARCHAR(255), latitude FLOAT, longitude FLOAT);
CREATE TABLE switches (switch_id UUID PRIMARY KEY NOT NULL, router_id UUID, switch_type VARCHAR(255), switch_vendor VARCHAR(255), switch_model VARCHAR(255), switch_ip_protocol VARCHAR(255), switch_ip_address VARCHAR(255), location_id int NULL, FOREIGN KEY (location_id) REFERENCES location(location_id), FOREIGN KEY (router_id) REFERENCES routers(router_id));
CREATE TABLE networks (network_id int NOT NULL PRIMARY KEY AUTO_INCREMENT, switch_id UUID, network_protocol VARCHAR(255), network_address VARCHAR(255), network_name VARCHAR(255), network_cidr VARCHAR(255), FOREIGN KEY (switch_id) REFERENCES switches(switch_id));